  db.exec('___1___');
  try {
    const r = db.prepare('UPDATE contas SET saldo = saldo - ? WHERE id = ? AND saldo >= ?').run(100, 1, 100);
    if (!r.changes) throw new Error('Saldo insuficiente');
    db.prepare('UPDATE contas SET saldo = saldo + ? WHERE id = ?').run(100, 2);
    db.exec('___2___'); res.end();
  } catch (err) { db.exec('___3___'); next(err); }
});

solution:
app.post('/transferir-demo', (req, res, next) => {
  db.exec('BEGIN IMMEDIATE');
  try {
    const r = db.prepare('UPDATE contas SET saldo = saldo - ? WHERE id = ? AND saldo >= ?').run(100, 1, 100);
    if (!r.changes) throw new Error('Saldo insuficiente');
    db.prepare('UPDATE contas SET saldo = saldo + ? WHERE id = ?').run(100, 2);
    db.exec('COMMIT'); res.end();
  } catch (err) { db.exec('ROLLBACK'); next(err); }
});

