solution:
app.post('/savepoint-demo', (req, res) => {
  db.exec('BEGIN');
  db.exec('SAVEPOINT parcial');
  db.prepare('UPDATE contas SET saldo = saldo + 1 WHERE id = 1').run();
  db.exec('ROLLBACK TO parcial');
